-- GENERATED by `python3 -m analytics render evidence` (analytics/specs/ceo_weekly_pulse.yml#orders_this_week; inputs sha256 f86822d969fa5fa3). Do not edit by hand.
SELECT
    o.order_id AS order_id,
    o.order_code AS order_code,
    strftime(o.ordered_at AT TIME ZONE 'Asia/Ho_Chi_Minh', '%d/%m %H:%M') AS ordered_at_local,
    COALESCE(ch.channel_name, 'Unknown') AS channel_name,
    c.full_name AS customer_name,
    o.status AS status,
    o.gross_revenue AS gross_revenue,
    o.discount_amount AS discount_amount,
    o.net_revenue AS net_sales
FROM main_marts.fact_orders o
LEFT JOIN main_marts.dim_customers c ON o.customer_key = c.customer_key
LEFT JOIN main_marts.dim_channels ch ON o.channel_key = ch.channel_key
WHERE o.scope_sales
  AND o.ordered_at >= timezone('Asia/Ho_Chi_Minh', CAST(CAST(date_trunc('week', (CAST(timezone('Asia/Ho_Chi_Minh', now()) AS DATE) - 1)) AS DATE) AS TIMESTAMP))
  AND o.ordered_at < timezone('Asia/Ho_Chi_Minh', CAST(((CAST(timezone('Asia/Ho_Chi_Minh', now()) AS DATE) - 1) + 1) AS TIMESTAMP))
ORDER BY o.ordered_at DESC
